def productsum(n):
    import math
    from heapq import heappush, heappop

    def min_product_sum(k):
        min_sum = float('inf')
        queue = [(1, 1, 1)]
        while queue:
            product, total, count = heappop(queue)
            if count == k:
                min_sum = min(min_sum, product)
                continue
            for i in range(2, int(math.sqrt(product)) + 1):
                if product % i == 0:
                    heappush(queue, (product // i, total + i, count + 1))
                    heappush(queue, (i, total + product // i, count + 1))
        return min_sum

    return sum(min_product_sum(k) for k in range(2, n + 1))
