def mix(s1, s2):
    from collections import Counter
    import re

    # Extract lowercase letters and count their frequency
    s1 = re.sub(r'[^a-z]', '', s1.lower())
    s2 = re.sub(r'[^a-z]', '', s2.lower())
    counter1 = Counter(s1)
    counter2 = Counter(s2)

    # Find the maximum frequency for each letter in both strings
    max_freq = {}
    for letter in set(counter1) | set(counter2):
        max_freq[letter] = max(counter1.get(letter, 0), counter2.get(letter, 0))

    # Filter out letters with maximum frequency less than or equal to 1
    max_freq = {letter: freq for letter, freq in max_freq.items() if freq > 1}

    # Create the result string
    result = []
    for letter in sorted(max_freq, key=lambda x: (-len(max_freq[x]), x)):
        count = max_freq[letter]
        if count in counter1 and count in counter2:
            result.append(f'=:{letter * count}')
        elif count in counter1:
            result.append(f'1:{letter * count}')
        else:
            result.append(f'2:{letter * count}')

    return '/'.join(result)
