def multiply(n, k):
    if n == 1 and k == 1:
        return 1
    if n == 1 or k == 1:
        return 0
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][1] = 1
    for i in range(2, n + 1):
        for j in range(2, k + 1):
            dp[i][j] = dp[i - 1][j] + j * dp[i // i][j - 1]
    return dp[n][k]
