    min_num = float('inf')
    max_num = float('-inf')
    count = 0

    def dfs(path, start, current_sum):
        nonlocal min_num, max_num, count
        if len(path) == digs:
            if current_sum == sum_dig:
                num = int(''.join(map(str, path)))
                if num < min_num:
                    min_num = num
                if num > max_num:
